args <- commandArgs(trailingOnly = TRUE)
infile <- args[[1]]
report_file <- args[[2]]
summary_file <- args[[3]]

x <- readRDS(infile)

safe_dim <- function(v) {
  d <- tryCatch(dim(v), error = function(e) NULL)
  if (is.null(d)) "" else paste(d, collapse = "x")
}

safe_names <- function(v, limit = 100L) {
  n <- tryCatch(names(v), error = function(e) NULL)
  if (is.null(n)) return("")
  paste(utils::head(n, limit), collapse = "|")
}

safe_rownames <- function(v, limit = 8L) {
  n <- tryCatch(rownames(v), error = function(e) NULL)
  if (is.null(n)) return("")
  paste(utils::head(n, limit), collapse = "|")
}

lines <- c(
  paste0("class\t", paste(class(x), collapse = "|")),
  paste0("isS4\t", isS4(x)),
  paste0("dim\t", safe_dim(x)),
  paste0("names\t", safe_names(x)),
  paste0("rownames_head\t", safe_rownames(x))
)

members <- data.frame(
  member = character(), class = character(), dim = character(),
  names_head = character(), rownames_head = character(),
  stringsAsFactors = FALSE
)
